pragma solidity ^0.8.0;

import {LoanInput, LoanOffer, Lien, SellInput, SellOffer, LienPointer} from "./BlendStructs.sol";

interface IBlend {
    event LoanOfferTaken(
        bytes32 offerHash,
        uint256 lienId,
        address collection,
        address lender,
        address borrower,
        uint256 loanAmount,
        uint256 rate,
        uint256 tokenId,
        uint256 auctionDuration
    );

    event Repay(uint256 lienId, address collection);

    event StartAuction(uint256 lienId, address collection);

    event Refinance(
        uint256 lienId,
        address collection,
        address newLender,
        uint256 newAmount,
        uint256 newRate,
        uint256 newAuctionDuration
    );

    event Seize(uint256 lienId, address collection);

    event BuyLocked(uint256 lienId, address collection, address buyer, address seller, uint256 tokenId);

    function amountTaken(bytes32 offerHash) external view returns (uint256);

    function liens(uint256 lienId) external view returns (bytes32);

    /*//////////////////////////////////////////////////
                    BORROW FLOWS
    //////////////////////////////////////////////////*/
    function borrow(
        LoanOffer calldata offer,
        bytes calldata signature,
        uint256 loanAmount,
        uint256 collateralId
    ) external returns (uint256 lienId);

    function repay(Lien calldata lien, uint256 lienId) external;

    /*//////////////////////////////////////////////////
                    REFINANCING FLOWS
    //////////////////////////////////////////////////*/
    function startAuction(Lien calldata lien, uint256 lienId) external;

    function seize(LienPointer[] calldata lienPointers) external;

    function refinance(Lien calldata lien, uint256 lienId, LoanOffer calldata offer, bytes calldata signature) external;

    function refinanceAuction(Lien calldata lien, uint256 lienId, uint256 rate) external;

    function refinanceAuctionByOther(
        Lien calldata lien,
        uint256 lienId,
